          if ($d.Kind -ne 'auto') { if (-not $have) { $sv = Get-CheckToRun $d $cache $bp $site $false; if ($sv) { $script:checkResults[$id] = $sv } }; continue }   # a sign-in or look check: its saved result, else it asks later
          if ($have -and -not $Force) { continue }
          $sv = Get-CheckToRun $d $cache $bp $site $Force
          if ($sv) { $script:checkResults[$id] = $sv; & $ui.RecRefresh; continue }
          $ui.P[0].Text = [string]$d.Name; $ui.RightL.Text = 'Check ' + ($i + 1) + ' of ' + $ids.Count; & $ui.SetBar 'all' ($i / [math]::Max(1, $ids.Count)) $true
          [System.Windows.Forms.Application]::DoEvents()
          $script:checkResults[$id] = Invoke-Check $d $bp $site { [System.Windows.Forms.Application]::DoEvents() }
          if ($ui.BaseRes.ContainsKey($id)) { $ui.BaseRes[$id] = $script:checkResults[$id] }   # Choose shows the newest result of a base check
          & $ui.RecRefresh   # an open Record shows the new result
        }
      } finally { $null = Save-CheckCache $script:checkResults $bp $site; $ui.Busy = $false; & $ui.SetBar 'all' 0 $false }
      if ($ui.Cancel) { $ui.Cancel = $false; & $ui.VChoose; return }   # Cancel: back to Choose, nothing changed (a check that ran is kept)
      & $ui.Next }
    $ui.CancelChecks = {
      # The check that is running ends first (a sign-in window cannot be closed from here); then RADE goes back to Choose.
      $ui.Cancel = $true; & $ui.Say1 'RADE stops after the check that is running.' }
    $ui.Next = {
      # One question at a time: the first FAILED check, else the first check that waits for you, else the plan.
      if ($ui.Form.IsDisposed -or $script:closing) { return }
      $ids = @($script:appChecks); $fails = @(); $needs = @()
      for ($i = 0; $i -lt $ids.Count; $i++) { $r = $script:checkResults[$ids[$i]]; if (-not $r -or $r.State -in 'NOT RUN', 'RUNNING') { $needs += $i } elseif ($r.State -eq 'FAILED') { $fails += $i } }
      if ($fails.Count) { & $ui.VFail $fails[0] $fails.Count; return }
      if ($needs.Count) { & $ui.VNeed $needs[0]; return }
      & $ui.VReady }
    # Shows the card of a failed check with what to do and a button to run it again. Takes the check number and the count of
    # failed checks.
    $ui.VFail = { param([int]$I, [int]$Count)
      $ids = @($script:appChecks); $ui.CurId = [string]$ids[$I]; $d = Get-CheckDef $ids[$I]; $r = $script:checkResults[$ids[$I]]
      # A check that runs on its own: "Run checks again". A sign-in or look-and-answer check: its own button, as on the card that asks for it.
      $again = $(if ($d.Kind -eq 'signin') { @{ Text = 'Sign in and check site rights'; Kind = 'primary'; Act = { & $ui.One } } } elseif ($d.Kind -eq 'guide') { @{ Text = 'Check Power Automate'; Kind = 'primary'; Act = { & $ui.One } } } else { @{ Text = 'Run checks again'; Kind = 'primary'; Act = { & $ui.Checks $true } } })
      $ok = @($ids | Where-Object { $script:checkResults[$_] -and $script:checkResults[$_].State -in 'PASSED', 'WARNING' }).Count
      & $ui.SetCard @{ View = 'fail'; Light = 'bad'; Kicker = ('Check ' + ($I + 1) + ' of ' + $ids.Count + $dot + 'FAILED'); Sentence = $(if ($Count -eq 1) { 'One check failed.' } else { [string]$Count + ' checks failed. This is the first.' })
        P = @([string]$d.Name, [string]$r.Detail, $(if ($r.Fix) { 'What to do: ' + $r.Fix } else { '' }))
        Buttons = @($again, $(if (& $ui.NeedSite) { @{ Text = 'Change the site address'; Act = { & $ui.VSite } } } else { $null }))
        Foot = ([string]$ok + ' of ' + $ids.Count + ' checks passed. RADE changes nothing until every check passes.'); Back = { & $ui.VChoose } }
      & $ui.ToFront }
    # Shows the card of a check that needs the user (a sign-in, a look-and-answer, or not run yet). Takes the check number.
    $ui.VNeed = { param([int]$I)
      $ids = @($script:appChecks); $ui.CurId = [string]$ids[$I]; $d = Get-CheckDef $ui.CurId; $r = $script:checkResults[$ui.CurId]
      $how = $(if ($d.Kind -eq 'signin') { 'CAC sign-in, read-only' } elseif ($d.Kind -eq 'guide') { 'You look and answer, read-only' } else { 'Not run yet' })
      $text = $(if ($d.Kind -eq 'signin') { 'Sign in and check site rights' } elseif ($d.Kind -eq 'guide') { 'Check Power Automate' } else { 'Run checks again' })
      & $ui.SetCard @{ View = 'need'; Light = 'you'; Kicker = ('Check ' + ($I + 1) + ' of ' + $ids.Count); Sentence = 'One check needs you.'
        P = @([string]$d.Name, $(if ($r -and $r.Detail) { [string]$r.Detail } elseif ($script:savedWhy[$ui.CurId]) { [string]$script:savedWhy[$ui.CurId] } else { $how }), $(if ($r -and $r.Fix) { 'What to do: ' + $r.Fix } else { '' }))
        Buttons = @(@{ Text = $text; Kind = 'primary'; Act = $(if ($d.Kind -eq 'auto') { { & $ui.Checks $true } } else { { & $ui.One } }) }); Back = { & $ui.VChoose } } }
    $ui.One = {
      # A check that needs you: the CAC sign-in opens its own window; the look-and-answer check shows a hand card.
      $d = Get-CheckDef $ui.CurId; $bp = Get-BasePath; $site = Get-SiteUrl $bp
      $ui.Cancel = $false
      & $ui.SetCard @{ View = 'checking'; Light = 'you'; Sentence = $(if ($d.Kind -eq 'signin') { 'Waiting for your sign-in.' } else { 'Checking.' }); P = @([string]$d.Name); Buttons = @(@{ Text = 'Cancel'; Always = $true; Act = { & $ui.CancelChecks } }) }
      $ui.Busy = $true
      try { $script:checkResults[$ui.CurId] = Invoke-Check $d $bp $site { [System.Windows.Forms.Application]::DoEvents() } }
      finally { $null = Save-CheckCache $script:checkResults $bp $site; $ui.Busy = $false; & $ui.RecRefresh }
      & $ui.ToFront; if ($ui.Cancel) { $ui.Cancel = $false; & $ui.VChoose; return }; & $ui.Next }
    $ui.VReady = {
      # The plan in three lines; the detail (each file, each step's box) is in the Record.
      if ($ui.Form.IsDisposed -or $script:closing) { return }
      $plan = Get-RoundPlan; $ui.Plan = $plan; $dep = Test-Deploy
      if (-not $plan.Found) {
        & $ui.SetCard @{ View = 'nodrive'; Light = 'bad'; Sentence = 'Your OneDrive folder was not found.'; P = @('RADE saves its files in your OneDrive folder.', 'What to do: open OneDrive from the Start menu and sign in. Then select "Look again".')
          Buttons = @(@{ Text = 'Look again'; Kind = 'primary'; Act = { & $ui.VReady } }); Back = { & $ui.VChoose } }
        return }
      $new = @($plan.Lines | Where-Object { $_ -match '^  New ' }).Count; $rep = @($plan.Lines | Where-Object { $_ -match '^  Replace ' }).Count
      $rec = 0; $in = $false; foreach ($l in $plan.Lines) { if ($l -match '^Clean-up \(runs first') { $in = $true } elseif ($in) { if ($l) { $rec++ } else { $in = $false } } }
      $n = [int][bool]($cleanup.Count -and $ui.Clean); $est = 0; $you = ''; $done = 0   # Clean-up counts as a step, as in the run's "Step k of n"
      foreach ($k in $script:appSteps) {
        if (-not $ui.Sel[[int]$k]) { if ($dep -and -not [bool]$steps[$k].Optional -and -not (Get-StepDefault $k)) { $done++ }; continue }
        $n++; $est += (Get-StepWeight $ui.Hist $steps[$k]).Seconds; if (-not $you -and $steps[$k].Kind -eq 'guide') { $you = 'Step ' + $n + ' needs you.' }
      }
      $ids = @($script:appChecks); $warn = @($ids | Where-Object { $script:checkResults[$_].State -eq 'WARNING' })
      $w1 = ''; if ($warn.Count) { $w1 = 'Warning: ' + (Get-CheckDef $warn[0]).Name + '. ' + $script:checkResults[$warn[0]].Detail + $(if ($warn.Count -gt 1) { ' (and ' + ($warn.Count - 1) + ' more in the Record)' } else { '' }) }
      # The saved site, by name, before anything is written (the Administrator, 2026-11-15): the steps use it with no
      # question, so a wrong site must show here. On the card only: a card's text never enters the log or the report.
      $siteName = ''; if ((& $ui.NeedSite) -and (Test-SiteUrl (Get-SiteUrl (Get-BasePath)))) { $siteName = ([string](Get-SiteUrl (Get-BasePath))).TrimEnd('/') -replace '^.*/', '' }
      # Start (R28, the Administrator, 2026-11-17): for an application that is installed and has a start script in its local folder, after the
      # checks pass. It is the main button when the installed version is this paste's version; when this paste is newer, Install stays
      # the main button.
      $startB = $null; $startPrimary = $false
      # Pause and resume (the PFM, 2026-11-20): a saved state of this round and build offers "Resume at step N of M" (main
      # button) and "Start over". A state that cannot be read, or of another build, goes to the Recycle Bin with a plain line.
      $rs = Read-RoundState (Get-BasePath); $rsNote = ''
      if ($rs.State -eq 'bad') { $null = Clear-RoundState (Get-BasePath); $rsNote = 'The saved progress of this round could not be read (' + $rs.Why + '), so the round starts over.' }
      elseif ($rs.State -eq 'other') { $null = Clear-RoundState (Get-BasePath); $rsNote = 'Saved progress of another build of this round was not used. The round starts over.' }
      $resB = $(if ($rs.State -eq 'ok') { @{ Text = 'Resume at step ' + $rs.Next + ' of ' + $rs.Total; Kind = 'primary'; Act = { & $ui.ResumeRun } } } else { $null })
      if ($dep -and [string]$script:app.Start) {
        $inst = Read-Installed (Get-InstalledKey $script:app)
        if ($inst -and $inst.installed -and (Get-StartPath)) { $startPrimary = ([string]$inst.installed.version -eq [string]$script:app.Version); $startB = @{ Text = 'Start ' + $script:app.Name; Kind = $(if ($startPrimary) { 'primary' } else { '' }); Act = { & $ui.StartApp } } }
      }
      if ($resB -and $startB) { $startB.Kind = '' }   # Resume is the one main button
      $hasWork = [bool]($n -or ($cleanup.Count -and $ui.Clean))
      $runB = @{ Text = $(if ($dep) { 'Install' } else { 'Run' }); Kind = $(if ($hasWork -and -not $startPrimary) { 'primary' } elseif ($hasWork) { '' } else { 'off' }); Act = { & $ui.Run } }
      if ($resB) { $runB = @{ Text = 'Start over'; Act = { & $ui.StartOver } } }   # in the place of Install or Run
      if ($resB -and $startB) { $startB.Kind = '' }   # B4 (UI standard v1): one primary; Resume wins
      & $ui.SetCard @{ View = 'ready'
        Kicker = $(if ($warn.Count) { [string]($ids.Count - $warn.Count) + ' checks passed' + $dot + $warn.Count + $(if ($warn.Count -eq 1) { ' warning' } else { ' warnings' }) } else { 'All ' + $ids.Count + ' checks passed' })
        Sentence = $(if ($dep) { 'Ready to install ' + $script:app.Name + ' ' + $script:app.Version + '.' } else { 'Ready to run round ' + $round + '.' })
        P = @(('Writes to ' + $plan.Shown + ': ' + $new + ' new files, ' + $rep + ' replaced, ' + $rec + ' moved to the Recycle Bin.'),
          ([string]$n + $(if ($n -eq 1) { ' step' } else { ' steps' }) + ', about ' + [math]::Max(1, [int][math]::Round($est / 60)) + ' min. ' + $you + $(if ($done) { ' ' + $done + ' already done for this version and off.' } else { '' })),
          $(if (Test-WordOpen) { 'Word is open. Save your documents and close Word before you start.' } else { '' }), $w1, $rsNote)
        Buttons = @($resB, $startB, $runB,   # B7: the Record is the link "Record (F2)"; B4: one primary (Resume when it shows)
          $(if ($siteName) { @{ Text = 'Change the site address'; Act = { & $ui.VSite } } } else { $null }))
        Foot = $(if ($siteName) { 'Site: ' + $siteName } else { '' })
        Field = $(if ($dep -and -not (Test-ShortcutMade)) { @{ Label = 'RADE shortcut in'; Text = (Get-ShortcutDir); Name = 'Folder for the RADE shortcut'; Button = 'Browse'; Act = { & $ui.BrowseDir } } } else { $null })
        Back = { & $ui.VChoose } }
      if ($ui.StartAfter) { $ui.StartAfter = $false; if ($startB) { & $ui.StartApp } else { & $ui.Say1 ('The checks passed, but ' + $script:app.Name + ' cannot be started: it is not recorded as installed, or its start file was not found. Select "Install" to install it again.') } } }   # Start on Maintenance: the checks passed, so the application starts
    # R29 N8 (the PFM, 17 Nov 26): the install asks where the RADE shortcut goes; the box starts with the Desktop folder.
    $ui.BrowseDir = {
      $pick = New-Object System.Windows.Forms.FolderBrowserDialog
      try { $pick.Description = 'Choose the folder for the RADE shortcut.'; $pick.ShowNewFolderButton = $true; $v = $ui.Field.Text.Trim(); if ($v -and (Test-Path -LiteralPath $v -PathType Container)) { $pick.SelectedPath = $v }
        if ([string]$pick.ShowDialog($ui.Form) -eq 'OK') { $ui.Field.Text = [string]$pick.SelectedPath } } catch { & $ui.Say1 'The folder window could not open. Type the folder in the box.' } finally { $pick.Dispose() } }

    # ==== Engine part: engine/ps/window/07-run.ps1 (sha256 2c647371c5ed)
    # RADE window part 07, the run: the callbacks Invoke-Round uses (log line, tick, step state), the Run button,
    # and the Done, Needs review and Stopped cards. Uses the card parts and Invoke-Round.
    # Joined into every bundle by engine/rade_build.py; Windows PowerShell 5.1.

    # ---- The run. Invoke-Round calls back: a log line ($ui.Say), a tick ($ui.Tick), a step that starts ($ui.OnStatus) and
    # a step that ends ($ui.OnStep). A step you do by hand comes in through $script:guideUi, what a step does now through
    # $script:nowUi, and the last question of a test round through $script:feedbackUi.
    $ui.Say = { param($t) Add-RunLog $t; $ui.Log.Add([string]$t); if ($ui.RecOn) { try { $ui.RecText.AppendText([string]$t + "`r`n") } catch { $null = $_ } }; try { [System.Windows.Forms.Application]::DoEvents() } catch { $null = $_ } }
    # L7 (the Administrator, 2026-11-19): the now-doing line under the step's bar. The engine calls this ($script:nowUi) with a
    # plain sentence for each item a step script reports (Get-NowText) and for a NOW line. Each text ends with "..." (its own
    # end mark goes; the Administrator, 2026-11-19) and is cut to $ui.NowLines lines; the line keeps its room. Takes the text.
    $ui.ShowNow = { param([string]$Text) try { if ($ui.View -eq 'run') { $x = $Text.Trim() -replace '[\s.,;:!?\u2026]+$', ''; $ui.NowRaw = $(if ($x) { $x + '...' } else { '' }); & $ui.CutNow; $ui.Now.Visible = $true } } catch { $null = $_ } }   # a line that cannot show never stops a step
    # Shows the whole now-doing text ($ui.NowRaw) cut to $ui.NowLines lines at the line's wrap width; runs again after a resize
    # ($ui.BreakAll), so a narrower window cuts it again from the whole text. Takes nothing; a failure is ignored.
    $ui.CutNow = { try { $w = [int](& $ui.GetWrap $ui.Now); $x = [string]$ui.NowRaw; if ($x) { $x = & $ui.FitLines (& $ui.BreakLong $x $ui.Now.Font $w) $ui.Now.Font $w $ui.NowLines }; if ([string]$ui.Now.Text -cne $x) { $ui.Now.Text = $x
        if ($x -and $null -ne $ui.EdgeX) { & $ui.SetLeft $ui.Now ([int]$ui.EdgeX - (& $ui.Ink $ui.Now)) } } } catch { $null = $_ } }   # its ink on the card edge for each new text (200 % run: 3 px off)   # a line that cannot show never stops a step
    # The engine's callback for the now-doing line (Add-StepLine): shows the text and emits nothing. Takes the text.
    $script:nowUi = { param($t) $null = & $ui.ShowNow ([string]$t) }
    # L8 (the Administrator, 2026-11-19): a step stays on the Run card for $ui.Layout.StepMs (engine/window.json) at least, so a
    # run of fast steps does not flicker. Waits out the rest of that time since the step showed. Takes nothing.
    $ui.HoldStep = {
      while ($ui.View -eq 'run' -and $null -ne $ui.StepAt -and -not $script:closing -and -not $ui.Form.IsDisposed -and ($ui.Clock.Elapsed.TotalMilliseconds - [double]$ui.StepAt) -lt [double]$ui.Layout.StepMs) { [System.Windows.Forms.Application]::DoEvents(); Start-Sleep -Milliseconds 15 } }
    # Draws the progress: both bars, the time in the step, the step fraction and the overall percent (the Administrator, 2026-11-19:
    # the percent only). Takes nothing; does nothing when no step runs.
    $ui.Paint = {
      if (-not $script:prog -or -not $script:stepStart) { return }
      $g = Get-Progress
      & $ui.SetBar 'all' ([math]::Max($g.All, $ui.Bars['all'].Target)) $true; & $ui.SetBar 'step' ([math]::Max($g.StepShown, $ui.Bars['step'].Target)) $true
      if ($ui.View -ne 'run') { return }
      & $ui.ShowTime
      $fr = $(if ($script:prog.Frac -ge 0) { [string]$script:prog.FracText } else { '' }); if ($ui.StepFrac.Text -ne $fr) { $ui.StepFrac.Text = $fr }   # one size ($ui.FixW): the bar keeps its width
      # R21 W6: a time left only when earlier runs give one; never "a guess".
      $rt = [string][int]($g.All * 100) + ' %'; if ($ui.RightL.Text -ne $rt) { $ui.RightL.Text = $rt } }
    # The time in this step (R28 N10): "4m 12s"; with hours "1h 04m 12s".
    $ui.Elapsed = { param([double]$Sec) $q = [int][math]::Floor([math]::Max(0, $Sec)); $h = [int][math]::Floor($q / 3600); $m = [int][math]::Floor(($q % 3600) / 60); $x = $q % 60
      if ($h) { return ('{0}h {1:00}m {2:00}s' -f $h, $m, $x) }; return ('{0}m {1:00}s' -f $m, $x) }
    # Shows the time in this step on the step line, once for each second. The time keeps one size from its widest value
    # ($ui.FixW), so the bar beside it never changes its width. Takes nothing; a failure is ignored.
    $ui.ShowTime = { try { if ($ui.View -eq 'run' -and $script:stepStart) { $t = & $ui.Elapsed ((Get-Date) - $script:stepStart).TotalSeconds; if ($ui.StepTime.Text -ne $t) { $ui.StepTime.Text = $t } } } catch { $null = $_ } }
    $ui.TimeT = New-Object System.Windows.Forms.Timer; $ui.TimeT.Interval = 1000; $ui.TimeT.Add_Tick({ & $ui.ShowTime })
    # The tick callback of a running step: repaints the bars and lets the window handle its events. Emits nothing.
    $ui.Tick = { $null = & $ui.Paint; [System.Windows.Forms.Application]::DoEvents() }   # a callback must emit nothing: its output would join the engine function's return value
    # Returns the title the window shows for a step (its manifest title, else its name). Takes the step name.
    $ui.TitleOf = { param([string]$Name) foreach ($s in @($steps)) { if ([string]$s.Name -ceq $Name) { return (Get-StepTitle $s) } }; return $Name }   # the title of the step with this name
    # Shows the run card: step k of n, the step name, the bars, Cancel and the next step that needs you.
    $ui.ShowRun = {
      & $ui.SetCard @{ View = 'run'; Kicker = $(if ($ui.StepI) { 'Step ' + $ui.StepI + ' of ' + $ui.StepN } else { 'Starting' }); Sentence = $(if (Test-Deploy) { 'Installing ' + $script:app.Name + '.' } else { 'Running round ' + $round + '.' })
        StepRow = $true; Buttons = @(@{ Text = 'Cancel'; Always = $true; Act = { $ui.Form.Close() } })   # asks first while a step runs (the window's X does the same)
        Range = @{ Kick = @('STARTING', 'STEP 00 OF 00'); StepName = @(@($steps | ForEach-Object { Get-StepTitle $_ }) + @('Clean-up')) }   # every step title: the step row keeps its place
        Right = '0 %'
        Foot = $(if (@($ui.Guides).Count) { 'RADE needs you next at "' + (& $ui.TitleOf $ui.Guides[0]) + '". Until then, keep this window open.' } elseif (-not (Test-Deploy) -and -not $ui.Asked) { 'RADE asks you one last question at the end. Until then, keep this window open.' } else { 'Nothing is needed from you. Keep this window open.' }) }
      $ui.StepName.Text = (& $ui.TitleOf $ui.StepNow); $null = & $ui.FitEdges; $null = & $ui.FitBar; $null = & $ui.ShowTime }   # the edge follows the ink of the new text's first letter (titles start with any letter)
    # Shows a new step on the Run card that is shown: its number in the line in capitals and its title. Both keep their size
    # ($ui.Range of the card), and the edges are fitted for the title's first letter. Takes the step number, the count and the name.
    $ui.ShowStep = { param([int]$I, [int]$N, [string]$Name) $ui.Kick.Text = ('Step ' + $I + ' of ' + $N).ToUpperInvariant(); $ui.StepName.Text = (& $ui.TitleOf $Name); $null = & $ui.FitEdges; $null = & $ui.FitBar }
    # Invoke-Round calls this when a step starts: keeps its name, start and estimate, and moves the run card on.
    # Takes the step index, the step count, the name and the estimate.
    $ui.OnStatus = { param($i, $count, $name, $estimate)
      $null = & $ui.HoldStep
      $script:statusBase = $name; $script:stepStart = Get-Date; $script:stepEst = $estimate
      if ($i -le 1) { $null = & $ui.SetBar 'all' 0 $true }
      $ui.StepI = [int]$i; $ui.StepN = [int]$count; $ui.StepNow = [string]$name
      if ($ui.View -ne 'run') { $null = & $ui.ShowRun } else { $null = & $ui.ShowStep $i $count $name }
      $null = & $ui.SetBar 'step' 0 $true; $ui.StepFrac.Text = ''; $null = & $ui.FitBar; $null = & $ui.ShowTime
      $doing = ''; foreach ($s in @($steps)) { if ([string]$s.Name -ceq [string]$name) { $doing = [string]$s.Doing } }; $null = & $ui.ShowNow $doing; $ui.StepAt = $ui.Clock.Elapsed.TotalMilliseconds   # L7: the step's own present-tense sentence, until its first item
      $null = & $ui.Paint; [System.Windows.Forms.Application]::DoEvents() }
    # Called when a step ends: keeps its state word (DONE, PASSED, SKIPPED, ...) from the result line and redraws. Takes the
    # step number and its result line.
    $ui.OnStep = { param($k, $line)
      $nm = [string]$steps[$k].Name + ': '; $rest = [string]$line; if ($rest.StartsWith($nm, [System.StringComparison]::Ordinal)) { $rest = $rest.Substring($nm.Length) }
      $st = 'DONE'; foreach ($w in 'NEEDS REVIEW', 'INTERRUPTED', 'FAILED', 'SKIPPED', 'PASSED') { if ($rest.StartsWith($w, [System.StringComparison]::Ordinal)) { $st = $w; break } }
      $ui.StepState[[int]$k] = $st; $null = & $ui.Paint }
    # Gives the "Window: OK" or "Window: NOT OK" line for the report, with the layout self-check when it is on. Takes
    # nothing; gives back the text.
    $ui.WindowLine = { $w = $(if ($ui.OkBox.Checked) { 'Window: OK' } else { 'Window: NOT OK - write here what overlapped or was cut off' }); if ($ui.LayOn -and ($env:RADE_LAYOUT -eq '1' -or -not (Test-Deploy))) { $w + "`r`n" + (& $ui.LayLine) } else { $w } }
    $ui.StartApp = {
      # The installed app opens from its local copy in its own powershell.exe process; then RADE closes.
      $p = Get-StartPath; if (-not $p) { & $ui.Say1 'The start file of this application was not found. Select "Install" to put it back.'; return }
      try { $pr = Start-Process -FilePath (Get-PowerShellExe) -ArgumentList ('-NoProfile -ExecutionPolicy Bypass -STA -File "' + $p + '"') -WorkingDirectory (Split-Path -Parent $p) -PassThru
        if ($pr) { $null = $pr.Handle }   # Windows PowerShell 5.1 keeps the exit code only when the handle is held
        # A start script that a policy blocks or that fails at once ends within a moment: say so and keep RADE open.
        if ($pr -and $pr.WaitForExit(2500) -and $pr.ExitCode -ne 0) { & $ui.Say1 ('The application stopped as soon as it started (exit code ' + $pr.ExitCode + '). Ask in the Teams channel.'); return }
        $ui.Started = $true; $ui.Form.Close() } catch { & $ui.Say1 'The application could not be started. Select "Start" again, or ask in the Teams channel.' } }
    # Starts the run: saves the shortcut folder, asks for the folder some steps need, then calls Invoke-Round with the
    # window callbacks and shows Done, Needs review or Stopped. Takes nothing.
    $ui.Run = {
      $ui.LinkDir = ''; $ui.FieldAsked = $false
      if ($ui.View -eq 'ready' -and $ui.FieldRow.Visible -and $ui.FieldL.Text -eq 'RADE shortcut in') {   # R29 N8: the folder for the RADE shortcut
        $d = $ui.Field.Text.Trim().Trim('"')
        if ($d -and -not (Test-Path -LiteralPath $d -PathType Container)) { & $ui.Say1 'That folder was not found. Select "Browse" to choose a folder, or empty the box for no shortcut.'; $script:resume = $null; return }
        $ui.LinkDir = $d; $ui.FieldAsked = $true; if ($d) { Save-ShortcutDir $d } }
      $dep = Test-Deploy; $ui.Running = $true; $ui.Asked = $false; $ui.StepAt = $null; $ui.Summary = @(); $ui.Log.Clear(); $ui.StepState = @{}; $ui.StepI = 0; $ui.StepNow = ''; $ui.Edit = $false
      $to = ''; if (-not $dep) { $to = [string](Get-MailTo (Get-BasePath)); $ui.ToBox.Text = $to }
      $sel = @(); $ui.Guides = @()
      for ($k = 0; $k -lt $steps.Count; $k++) { $on = [bool]($script:appSteps -contains $k -and $ui.Sel[[int]$k]); $sel += $on; if ($on -and $steps[$k].Kind -eq 'guide') { $ui.Guides += [string]$steps[$k].Name } }
      # A step that needs a folder asks for it now (a Windows dialog); Cancel skips that step. A resume does not ask again
      # for a step it keeps.
      $kept = $(if ($script:resume) { Get-ResumeKept $script:resume } else { @{} })
      $answers = @()
      for ($k = 0; $k -lt $steps.Count; $k++) {
        $a = ''
        if ($sel[$k] -and $steps[$k].AskParam -and -not $kept.ContainsKey([string]$steps[$k].Name)) {
          $pick = New-Object System.Windows.Forms.FolderBrowserDialog
          $pick.Description = $steps[$k].AskPrompt; $pick.ShowNewFolderButton = $false
          if ([string]$pick.ShowDialog($ui.Form) -eq 'OK') { $a = [string]$pick.SelectedPath } else { $sel[$k] = $false; $ui.Guides = @($ui.Guides | Where-Object { $_ -ne [string]$steps[$k].Name }); $ui.Log.Add($steps[$k].Name + ': skipped (no folder picked)') }
          $pick.Dispose()
        }
        $answers += $a
      }
      $ui.Bars['all'].Fill = $ui.C.Blue; & $ui.SetBar 'all' 0 $true; & $ui.SetBar 'step' 0 $true
      & $ui.ShowRun; $ui.TimeT.Start()
      $checkLines = Get-CheckSummary $script:checkResults
      $script:roundStart = Get-Date
      try {
        $ui.Summary = Invoke-Round ([bool]($cleanup.Count -and $ui.Clean)) $sel $to $ui.Say $ui.Tick $ui.OnStep $ui.OnStatus $ui.WindowLine $answers $checkLines
        & $ui.HoldStep; $script:stepStart = $null; $ui.Running = $false
        if (-not ($script:closing -or $ui.Form.IsDisposed)) { & $ui.VDone }   # closed in the last moments of the run: no clipboard, no folder
      } catch {
        $script:stepStart = $null; $ui.Running = $false
        if ($script:closing -or $ui.Form.IsDisposed) { return }   # Exit during a step: the report on disk says STOPPED
        $msg = 'STOPPED: ' + (ConvertTo-Masked ([string]$_)); & $ui.Say $msg
        $what = [string](Get-WhatToDo $msg); if ($what) { & $ui.Say $what }
        & $ui.VStopped $msg.Substring(9) $what
      } finally { $script:resume = $null; $ui.Running = $false; try { $ui.TimeT.Stop() } catch { $null = $_ }; $sv = $ui.StepState; & $ui.InitSel; $ui.StepState = $sv } }
    # Pause and resume (the PFM, 2026-11-20; docs/engine.md "Pause and resume"): runs the round again from its saved state.
    # The steps that passed stay done; the step that was running and the steps after it run. Takes nothing.
    $ui.ResumeRun = {
      $st = Read-RoundState (Get-BasePath)
      if ($st.State -ne 'ok') { $null = Clear-RoundState (Get-BasePath); & $ui.VReady; & $ui.Say1 'The saved progress could not be read, so the round starts over. Select the main button to start.'; return }
      $sel = Get-ResumeSelection $st.Doc; for ($k = 0; $k -lt $steps.Count; $k++) { if ($script:appSteps -contains $k) { $ui.Sel[[int]$k] = [bool]$sel[$k] } }
      $script:resume = $st.Doc; & $ui.Run }
    # Start over: the saved state goes to the Recycle Bin, then the round runs from its first step. Takes nothing.
    $ui.StartOver = { $why = Clear-RoundState (Get-BasePath); if ($why) { & $ui.Say1 ('The saved progress could not be moved to the Recycle Bin (' + $why + ').'); return }; $script:resume = $null; & $ui.Run }
    $ui.MadeText = {
      # Deploy: how many things the installs of this application made, by kind (the list is in the Record).
      $c = [ordered]@{}; $e = (Read-Installed (Get-InstalledKey $script:app))
      if ($e -and $e.steps) { foreach ($n in @($e.steps.Keys)) { foreach ($m in @($e.steps[$n].made)) { if ($null -ne $m) { $k = [string]$m.kind; if ($c.Contains($k)) { $c[$k] = [int]$c[$k] + 1 } else { $c[$k] = 1 } } } } }
      if (-not $c.Count) { return '' }
      $parts = @(); foreach ($k in @($c.Keys)) { $parts += ([string]$c[$k] + ' ' + $k + $(if ($c[$k] -ne 1) { 's' } else { '' })) }
      return ('The installs of this application made: ' + ($parts -join ', ') + '.') }
    # Copies the summary (else the log) to the clipboard and says "Copied.". Takes nothing.
    $ui.Copy = {
      $t = $(if (@($ui.Summary).Count) { @($ui.Summary) } else { @($ui.Log) }) -join "`r`n"
      try { [System.Windows.Forms.Clipboard]::SetText($t); & $ui.Say1 'Copied.' } catch { & $ui.Say1 'The clipboard is busy. Select the button again.' } }
    # Opens the results folder in Explorer, when there is one. Takes nothing.
    $ui.Open = { if ($script:resultsDir) { Start-Process -FilePath 'explorer.exe' -ArgumentList ('"' + $script:resultsDir + '"') } }
    # Shows the card at the end of a run: Done when every step passed, else Needs review with the first problem. Copies the
    # summary and opens the folder in a test round. Takes nothing.
    $ui.VDone = {
      $sum = @($ui.Summary); $dep = Test-Deploy; $bad = ([string]$sum[0] -match 'NEEDS REVIEW'); $made = ''; if ($dep) { $made = [string](& $ui.MadeText) }
      $took = Format-Duration ((Get-Date) - $script:roundStart).TotalSeconds
      $ui.Bars['all'].Fill = $(if ($bad) { $ui.C.Blue } else { $ui.C.Green }); & $ui.SetBar 'all' $(if ($bad) { $ui.Bars['all'].Target } else { 1 }) $true
      $mail = $(if ($script:draftMade) { 'An Outlook draft is open with the summary and all result files. Review it, then select Send.' } else { 'The results folder is open and the summary is on the clipboard. Paste it into an e-mail and attach the files.' })
      $iconNote = ''; if ($dep -and -not $bad) { $null = Save-RunnerCopy; $iconNote = $(if ($ui.FieldAsked -and -not $ui.LinkDir -and (Get-DesktopDir)) { 'The shortcut folder box was empty, so RADE made no shortcut. Open RADE from the RADE page instead.' } else { [string](Add-DesktopIcon ([string]$ui.LinkDir)) }) }   # R28: the runner copy and the desktop shortcut (a deploy that passed)
      if (-not $bad) {
        $inst = ($dep -and (Get-InstalledText $script:app) -match 'is installed$')
        # Start (R28 fix: after a first install the Done card had no Start button): the checks passed before the install.
        $startB = $(if ($inst -and [string]$script:app.Start -and (Get-StartPath)) { @{ Text = 'Start ' + $script:app.Name; Kind = 'primary'; Act = { & $ui.StartApp } } } else { $null })
        & $ui.SetCard @{ View = 'done'; Tick = $true; Kicker = $(if ($dep -and -not $inst) { 'Passed' } else { 'All steps passed' }); Right = $took
          Sentence = $(if (-not $dep) { 'Round ' + $round + ' is done.' } elseif ($inst) { $script:app.Name + ' ' + $script:app.Version + ' is installed.' } else { 'The run passed, but version ' + $script:app.Version + ' is not recorded as installed.' })
          P = @($(if ($dep -and -not $inst) { 'Some steps were off or skipped. Run again with every step on.' } else { '' }), $(if ($dep) { 'Nothing was sent. The report stays on this computer.' } else { $mail }), $made, $iconNote)
          Buttons = @($startB, @{ Text = 'Close'; Kind = $(if ($startB) { '' } else { 'primary' }); Act = { $ui.Form.Close() } }, @{ Text = 'Open results folder'; Act = { & $ui.Open } }, @{ Text = 'Copy summary'; Act = { & $ui.Copy } })
          Test = (-not $dep); Back = { & $ui.VReady } }
      } else {
        # The first step that needs review, with its help line from the manifest; the rest is in the Record.
        $one = ''; $what = ''; $more = 0
        for ($k = 0; $k -lt $sum.Count; $k++) { if ([string]$sum[$k] -match ': (NEEDS REVIEW|FAILED) ') { if ($one) { $more++ } else { $one = [string]$sum[$k]; if ($k + 1 -lt $sum.Count -and [string]$sum[$k + 1] -match '^\s+What to do: ') { $what = ([string]$sum[$k + 1]).Trim() } } } }
        if (-not $one) { $one = 'A file, the clean-up or a result file needs review. The Record shows which.' }
        & $ui.SetCard @{ View = 'review'; Light = 'bad'; Kicker = 'Needs review'; Right = 'Needs review'; Sentence = $(if ($dep) { 'The install is not complete.' } else { 'The round needs review.' })
          P = @(($one + $(if ($more) { ' (and ' + $more + ' more in the Record)' } else { '' })), $what, $(if ($dep) { 'Steps that passed stay done. If you paste the block again, RADE runs only what is left.' } else { $mail }))
          Help = $(if ($dep) { Get-HelpLine } else { '' }); Note = $(if ($dep) { '"Copy summary" puts the report on the clipboard. Paste it in the channel. Nothing was sent.' } else { '' })
          Buttons = @(@{ Text = 'Copy summary'; Kind = 'primary'; Act = { & $ui.Copy } }, @{ Text = 'Open results folder'; Act = { & $ui.Open } }, @{ Text = 'Close'; Act = { $ui.Form.Close() } })
          Test = (-not $dep); Back = { & $ui.VReady } }
      }
      if (-not $dep) { & $ui.Copy; if (-not $script:draftMade) { & $ui.Open } }   # a test round: the summary is on the clipboard, and with no draft the folder opens
      & $ui.ToFront }
    # Shows the Paused card (the PFM, 2026-11-20): the sign-in failed in a step (the CAC is out), so the round paused at that
    # step; Resume runs it again. Takes the reason ("INTERRUPTED: ..."); does nothing when the window is closing.
    $ui.VPaused = { param([string]$Why)
      if ($script:closing -or $ui.Form.IsDisposed) { return }
      $p1 = (($Why.Substring(13) -replace '\. Insert your CAC, then select Resume$', '') -replace '^t', 'T') + '.'
      & $ui.SetCard @{ View = 'stopped'; Kicker = 'Paused'; Right = 'Paused'; Sentence = 'Insert your CAC, then select Resume.'
        P = @($p1, 'The steps that passed stay done. Resume runs this step again.'); Back = { & $ui.VReady }
        Buttons = @(@{ Text = 'Resume'; Kind = 'primary'; Act = { & $ui.ResumeRun } }, @{ Text = 'Copy the log'; Act = { & $ui.Copy } }, @{ Text = 'Close'; Act = { $ui.Form.Close() } }) }
      & $ui.ToFront }
    # Shows the Stopped card with why the run stopped and what to do. Takes the reason and the help text; does nothing when
    # the window is closing.
    $ui.VStopped = { param([string]$Why, [string]$What)
      if ($script:closing -or $ui.Form.IsDisposed) { return }
      $dep = Test-Deploy
      if ($Why -match '^INTERRUPTED: ') { & $ui.VPaused $Why; return }   # the sign-in failed (CAC out): Paused, not Stopped
      & $ui.SetCard @{ View = 'stopped'; Light = 'bad'; Kicker = 'Stopped'; Right = 'Stopped'; Sentence = $(if ($dep) { 'The install stopped.' } else { 'The round stopped.' })
        P = @(($Why.Substring(0, 1).ToUpperInvariant() + $Why.Substring(1)), $What, 'The report in the results folder says STOPPED.'); Help = $(if ($dep) { Get-HelpLine } else { '' })
        Buttons = @(@{ Text = 'Copy the log'; Kind = 'primary'; Act = { & $ui.Copy } }, @{ Text = 'Try again'; Act = { & $ui.VReady } }, @{ Text = 'Close'; Act = { $ui.Form.Close() } }); Back = { & $ui.VReady } }
      & $ui.ToFront }
    $ui.OkBox.Add_CheckedChanged({ if (-not $ui.OkBox.Checked) { & $ui.Say1 'Select "Make e-mail draft" to make a draft that says "Window: NOT OK".' } elseif ($ui.Note.Text -match '^Select "Make e-mail draft"') { & $ui.Say1 '' } })   # ticking again removes only this note
    $ui.DraftB.Add_Click({
      $to = $ui.ToBox.Text.Trim()
      if ($to -and -not (Test-MailTo $to)) { & $ui.Say1 'The e-mail address does not look right.'; return }
      try { $null = Save-MailTo (Get-BasePath) $to } catch { $null = $_ }
      $why = Save-RoundDraft $script:resultsDir $ui.Summary $to (& $ui.WindowLine)
      & $ui.Say1 $(if ($why) { 'The Outlook draft could not be created (' + $why + ').' } else { 'The Outlook draft is open.' }) })

    # ==== Engine part: engine/ps/window/08-hand-step.ps1 (sha256 70cc10b09272)
    # RADE window part 08, a hand step: the cards for a step the user does by hand (It failed, questions,
    # open the address) and $script:guideUi, which the engine waits in until the user answers.
    # Joined into every bundle by engine/rade_build.py; Windows PowerShell 5.1.

    # ---- A step you do by hand, or a check you answer by looking (R13, R14, R18): the card holds the numbered lines, the
    # address (it can be changed; it is remembered in Config), the file path on the clipboard, and the answers. The engine
    # waits in $script:guideUi until an answer is set: OK = Done or Yes, No, Abort = It failed (with the error text),
    # Cancel = Skip, Not now, or the window closed. Enter never answers here: Done needs a deliberate click.
    $ui.VHand = {
      $st = $ui.G.Step; $file = [string]$ui.G.File; $hide = @($st.Hide)
      $clip = $(if (-not $file) { '' } elseif (Copy-TextToClipboard $file) { 'The path of ' + $st.File + ' is on the clipboard.' } else { 'Select "Copy file path" to put the path of ' + $st.File + ' on the clipboard.' })
      $two = $(if ($st.NoText) { @{ Text = [string]$st.NoText; Act = { $ui.Answer = 'No' } } } else { @{ Text = 'It failed'; Act = { & $ui.VHandFail } } })
      # R28 N1: the address row only when the step has an address (or a saved one it can take); N6: the file's full path on the card.
      $addr = [bool]($ui.GUrl -or $st.UrlConfig); $dw = $(if ($st.DoneText) { [string]$st.DoneText } else { 'Done' })
      # E1 (the Administrator, 2026-11-19): the step's "hide" takes buttons off the card; one button always stays (the build checks it).
      $one = @{ Text = $dw; Kind = 'primary'; Act = { $ui.Answer = 'OK' } }; $three = @{ Text = $(if ($st.SkipText) { [string]$st.SkipText } else { 'Skip' }); Act = { $ui.Answer = 'Cancel' } }
      $bs = @($(if ($hide -notcontains 'done') { $one }), $(if ($hide -notcontains 'failed') { $two }), $(if ($hide -notcontains 'skip') { $three }))
      $close = $(if ($hide -contains 'done') { '' } elseif ($addr) { 'When you finish in the browser, come back to this window and select "' + $dw + '".' } else { 'When you finish, select "' + $dw + '".' })
      & $ui.SetCard @{ View = 'hand'; Light = 'you'; Kicker = $(if ($ui.Running -and $ui.StepI) { 'Step ' + $ui.StepI + ' of ' + $ui.StepN } else { '' }); Sentence = (Get-StepTitle $st)
        P = @([string]$st.Note); Lines = @($st.Guide); Close = $close
        Field = $(if ($addr) { @{ Label = 'Address'; Text = $ui.GUrl; Name = 'Address to open'; Button = 'Open in browser'; Act = { & $ui.OpenUrl } } } else { $null }); Path = $file; Links = [bool]$file; Note = $clip
        Buttons = $bs; NoAccept = $true; Focus = $(if ($addr) { 'fieldbutton' } else { 'text' }) } }
    # Shows the card where the user pastes the error of a hand step that failed; its button sets the answer to Abort. Takes
    # nothing.
    $ui.VHandFail = {
      & $ui.SetCard @{ View = 'handfail'; Light = 'you'; Kicker = 'It failed'; Sentence = 'What did the error say?'; P = @('Paste the error message here. Do not include names or a site address.'); Err = $true
        Buttons = @(@{ Text = 'Report the failure'; Kind = 'primary'; Act = { $script:guideError = [string]$ui.ErrBox.Text; $ui.Answer = 'Abort' } }); Back = { & $ui.VHand }; NoAccept = $true; Focus = 'err' } }
    # A question of a hand step (manifest "answers"), after Done: the prompt is the sentence; yes/no and pick answer with
    # one button per word, a text with one line (10,000 characters at most; empty is allowed; R28: kept whole) and "Continue". No Back.
    $ui.ReplyActs = @({ $ui.Reply = [string]$ui.B[0].Text }, { $ui.Reply = [string]$ui.B[1].Text }, { $ui.Reply = [string]$ui.B[2].Text }, { $ui.Reply = [string]$ui.B[3].Text })
    # Shows one question of a hand step (text, yes or no, or a pick). The first sentence of the prompt is the headline.
    # Takes the question, its number and the count; the answer is set in $ui.Reply.
    $ui.VAnswer = { param($Q, [int]$I, [int]$N)
      $ui.Reply = $null
      $c = @{ View = 'answer'; Light = 'you'; Kicker = ($(if ($ui.Running -and $ui.StepI) { 'Step ' + $ui.StepI + ' of ' + $ui.StepN + $dot } else { '' }) + 'Question ' + $I + ' of ' + $N); Sentence = [string]$Q.Prompt }
      # The prompt's first sentence (up to the first "?", "." or ":" followed by a space or the end) is the headline; the rest
      # is a body line under it (the Administrator, 2026-11-15, rework B). A first sentence too long for one line shrinks ($ui.FitSent).
      if ([string]$Q.Prompt -match '^(.+?[?.:])(?:\s+(\S.*))?$') { $c.Sentence = $Matches[1]; if ($Matches[2]) { $c.P = @($Matches[2].Trim()) } }
      if ($Q.Kind -eq 'text') { $c.Field = @{ Label = 'Your answer'; Text = ''; Name = [string]$Q.Prompt; Max = 10000; Above = $true }
        $c.Focus = 'field'; $c.Buttons = @(@{ Text = 'Continue'; Kind = 'primary'; Act = { $ui.Reply = [string]$ui.Field.Text } }) }
      else { $ws = @($(if ($Q.Kind -eq 'yesno') { 'Yes', 'No' } else { $Q.Choices })); $c.Buttons = @(for ($k = 0; $k -lt $ws.Count; $k++) { @{ Text = [string]$ws[$k]; Act = $ui.ReplyActs[$k] } }) }
      & $ui.SetCard $c }
    # E2 (the Administrator, 2026-11-19): after an answer that the manifest marks as a failure ("failOn"), the card where the
    # user pastes the error text. Its button keeps the text in $script:guideError and sets $ui.Reply. No Back. Takes nothing.
    $ui.VAnswerFail = {
      $ui.Reply = $null
      & $ui.SetCard @{ View = 'answerfail'; Light = 'you'; Kicker = ($(if ($ui.Running -and $ui.StepI) { 'Step ' + $ui.StepI + ' of ' + $ui.StepN + $dot } else { '' }) + 'It failed'); Sentence = 'What did the error say?'
        P = @('Paste the error message here. Do not include names or a site address. If there is no message, leave the box empty.'); Err = $true
        Buttons = @(@{ Text = 'Continue'; Kind = 'primary'; Act = { $script:guideError = [string]$ui.ErrBox.Text; $ui.Reply = 'ok' } }); NoAccept = $true; Focus = 'err' } }
    # Waits until the user answers the card that is shown ($ui.Reply is set) or the window closes. Takes nothing.
    $ui.WaitReply = { while ($null -eq $ui.Reply -and -not $script:closing -and -not $ui.Form.IsDisposed) { [System.Windows.Forms.Application]::DoEvents(); Start-Sleep -Milliseconds 25 } }
    # Asks the questions of a hand step, one card each, in order; a question with "showIf" shows only after one of its
    # answers to the earlier question (E3). Keeps the answers in $script:guideAnswers and the answers that mean a failure
    # in $script:guideFail; after the first of those it asks for the error text. Takes the step; gives back nothing.
    $ui.AskAnswers = { param($Step)
      $qs = @($Step.Answers | Where-Object { $_ })
      for ($i = 0; $i -lt $qs.Count -and -not $script:closing -and -not $ui.Form.IsDisposed; $i++) {
        $q = $qs[$i]; if ($q.ShowKey -and @($q.ShowIn) -cnotcontains [string]$script:guideAnswers[[string]$q.ShowKey]) { continue }
        $null = & $ui.VAnswer $q ($i + 1) $qs.Count; $null = & $ui.WaitReply
        if ($null -eq $ui.Reply) { return }
        $v = [string]$ui.Reply; $script:guideAnswers[[string]$q.Key] = $v
        if (@($q.FailOn) -ccontains $v) { $script:guideFail += ([string]$q.Key + ': ' + $v); if (@($script:guideFail).Count -eq 1) { $null = & $ui.VAnswerFail; $null = & $ui.WaitReply } }
      } }
    # Opens the address in the box in the browser and remembers it (also in its file). Takes nothing; says so when the
    # address does not start with https://, or is not on the host of the step's own address (the Administrator, 2026-11-17).
    $ui.OpenUrl = {
      $u = $ui.Field.Text.Trim()
      if ($u -notmatch '^https://') { & $ui.Say1 'The address must start with https://'; return }
      $fixed = [string]$ui.G.Step.Url
      if (-not $fixed) { & $ui.Say1 'This step gives no address of its own, so RADE cannot open one from here.'; return }
      if (-not (Test-SameHost $u $fixed)) { & $ui.Say1 ('The address must be on ' + ([uri]$fixed).Host + ', like the address this step gives.'); return }
      $ui.GUrl = $u; try { if ($ui.G.UrlFile) { Set-Content -LiteralPath $ui.G.UrlFile -Value $u -Encoding UTF8 } } catch { $null = $_ }
      try { Start-Process -FilePath $u; & $ui.Say1 'Opened in your browser. Do the steps on this card, then come back to this window.' } catch { & $ui.Say1 ('The browser could not be opened: ' + $_.Exception.Message) } }
    $ui.CopyPathB.Add_Click({ & $ui.Say1 $(if (Copy-TextToClipboard ([string]$ui.G.File)) { 'File path copied. Press Ctrl+V in the "File name" box' } else { 'The clipboard is busy. Select "Copy file path" again.' }) })
    $ui.PageB.Add_Click({ try { Start-Process -FilePath $radeUrl } catch { & $ui.Say1 'The browser could not be opened. Open the RADE page from your bookmarks.' } })
    $ui.ShowFileB.Add_Click({ if ($ui.G.File) { Start-Process -FilePath 'explorer.exe' -ArgumentList ('/select,"' + $ui.G.File + '"') } })
    # Shows a hand step and waits until the user answers, then asks the step's questions; a step with "answersOnly" shows its
    # questions at once (E2). Takes the step, the file path, the address and the address file; gives back OK, Abort or Cancel.
    $script:guideUi = { param($Step, [string]$File, [string]$Url, [string]$UrlFile)
      $ui.G = @{ Step = $Step; File = $File; UrlFile = $UrlFile }; $ui.GUrl = $Url; $script:guideError = ''; $ui.Answer = ''; $was = $ui.Busy; $ui.Busy = $false
      $script:guideAnswers = @{}; $script:guideFail = @()
      if ($Step.AnswersOnly) { $ui.Answer = 'OK'; $null = & $ui.ToFront }
      else { $null = & $ui.VHand; $null = & $ui.ToFront
        while (-not $ui.Answer -and -not $script:closing -and -not $ui.Form.IsDisposed) { [System.Windows.Forms.Application]::DoEvents(); Start-Sleep -Milliseconds 25 } }
      # After Done (not after "It failed" or Skip): the step's questions, one card each, in order. Their time is the step's time.
      if ($ui.Answer -eq 'OK') { $null = & $ui.AskAnswers $Step }
      $ui.Busy = $was; $res = [string]$ui.Answer; if (-not $res) { $res = 'Cancel' }
      if ($Step.AnswersOnly -and ($script:closing -or $ui.Form.IsDisposed)) { $res = 'Cancel' }   # the window closed before the last answer
      $ui.Guides = @($ui.Guides | Where-Object { $_ -ne [string]$Step.Name })
      if ($ui.Running -and -not $script:closing) { $null = & $ui.ShowRun }
      return $res }
    # L4 (the Administrator, 2026-11-19): the last card of a test round, "Anything else about this round or the app?". The
    # text is optional and takes up to 10,000 characters, like every text answer (R34, R7); a pasted block becomes one line ($ui.PasteLine); the engine puts it into the report under the line "Other feedback:" (Get-RoundFeedback). Takes
    # nothing; waits for Continue; gives back the text ('' when the window closed).
    $script:feedbackUi = {
      $null = & $ui.HoldStep   # L8: the last step stays on the Run card for its minimum time first
      $was = $ui.Busy; $ui.Busy = $false; $ui.Reply = $null; $ui.Asked = $true
      $null = & $ui.SetCard @{ View = 'feedback'; Light = 'you'; Kicker = 'Last question'; Sentence = 'Anything else about this round or the app?'
        P = @('This is optional. Do not type names or addresses.'); Field = @{ Label = 'Your answer'; Text = ''; Name = 'Anything else about this round or the app?'; Max = 10000; Above = $true }; Focus = 'field'
